style.css:
@-moz-document url-prefix("https://www.netflix.com/browse") {
html,
    body,
    #appMountPoint {
        background: transparent !important;
    }

    body::before {
        content: "";
        position: fixed;
        inset: 0;
        z-index: -9999;
        
        background-image:
            linear-gradient(
                rgba(0, 0, 0, 0.35),
                rgba(0, 0, 0, 0.55)
            ),
            url("https://static.vecteezy.com/system/resources/thumbnails/037/918/540/small/ai-generated-trendy-leopard-fur-texture-golden-fur-and-black-spots-natural-animal-furry-background-concept-is-softness-comfort-and-luxury-can-be-used-as-backdrop-fashion-textile-interior-photo.jpeg");

        background-size: cover;
        background-position: center;
        background-repeat: no-repeat;
    }

    #appMountPoint > div {
        background: transparent !important;
    }
}
